# Client Examples

Examples below use `GET /_meta`.

## cURL

```bash
curl -X GET "https://api.example.com/_meta" \
  -H "Authorization: Bearer ${DD_API_KEY}"
```

## JavaScript

```javascript
const response = await fetch('https://api.example.com/_meta', {
  method: 'GET',
  headers: {
    'Authorization': `Bearer ${process.env.DD_API_KEY}`
  }
});
const data = await response.json();
```

## Python

```python
import os
import requests

headers = {
    'Authorization': f"Bearer {os.environ['DD_API_KEY']}"
}

response = requests.get('https://api.example.com/_meta', headers=headers)
response.raise_for_status()
data = response.json()
```

## Go

```go
package main

import (
  "fmt"
  "net/http"
  "os"
)

func main() {
  req, _ := http.NewRequest("GET", "https://api.example.com/_meta", nil)
  req.Header.Set("Authorization", "Bearer "+os.Getenv("DD_API_KEY"))
  resp, err := http.DefaultClient.Do(req)
  if err != nil { panic(err) }
  defer resp.Body.Close()
  fmt.Println(resp.Status)
}
```

## Ruby

```ruby
require 'net/http'
require 'json'

uri = URI('https://api.example.com/_meta')
request = Net::HTTP::Get.new(uri)
request['Authorization'] = 'Bearer ' + ENV.fetch('DD_API_KEY')
response = Net::HTTP.start(uri.hostname, uri.port, use_ssl: uri.scheme == 'https') { |http| http.request(request) }
puts response.body
```

## PHP

```php
<?php
$ch = curl_init();
curl_setopt($ch, CURLOPT_URL, 'https://api.example.com/_meta');
curl_setopt($ch, CURLOPT_CUSTOMREQUEST, 'GET');
curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
curl_setopt($ch, CURLOPT_HTTPHEADER, [
    'Authorization: Bearer ' . getenv('DD_API_KEY')
]);
$response = curl_exec($ch);
curl_close($ch);
echo $response;
```

## Java

```java
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;

var client = HttpClient.newHttpClient();
var builder = HttpRequest.newBuilder(URI.create("https://api.example.com/_meta"));
builder.header("Authorization", "Bearer " + System.getenv("DD_API_KEY"));
builder.method("GET", HttpRequest.BodyPublishers.noBody());
var response = client.send(builder.build(), HttpResponse.BodyHandlers.ofString());
System.out.println(response.body());
```
